data.minimal_example:
final queue = QueueIt<int>(
  parallel: 2,
  retries: 3,
  itemHandler: (item) async {
    print('Processing ${item.data}');
    await Future<void>.delayed(const Duration(seconds: 1));
  },
);
queue.onUpdate.listen((snapshot) {
  print('Event: ${snapshot.event.name}');
});
queue.add(1);
queue.add(2);
queue.start();
